import manifest from '../content/media-manifest.json'

interface ManifestEntry {
  w: number
  h: number
  widths: number[]
  crisp: boolean
}

const entries = manifest as Record<string, ManifestEntry>

export interface ResolvedImage {
  src: string
  srcSet: string
  width: number
  height: number
  crisp: boolean
}

/**
 * Resolves a media key (e.g. "kfs/kfs2_gdt") to the responsive WebP files
 * generated by scripts/optimize-media.mjs.
 */
export function resolveImage(key: string): ResolvedImage {
  const entry = entries[key]
  if (!entry) throw new Error(`Unknown media "${key}". Run "npm run media" after adding files to media-src/.`)

  const url = (w: number) => `/media/${key}-${w}.webp`
  const largest = entry.widths[entry.widths.length - 1]
  return {
    src: url(largest),
    srcSet: entry.widths.map((w) => `${url(w)} ${w}w`).join(', '),
    width: entry.w,
    height: entry.h,
    crisp: entry.crisp,
  }
}
